def solve(facts):
    alphabet = facts["alphabet"]
    length = facts["length"]
    modulus = facts["modulus"]
    residue = facts["residue"]
    sum_min = facts["sum_min"]
    sum_max = facts["sum_max"]
    target_digit = facts["target_digit"]
    target_count = facts["target_count"]
    # State: last digit, residue, digit sum, target-digit count.
    dp = {}
    for digit in alphabet:
        key = (digit, digit % modulus, digit, int(digit == target_digit))
        dp[key] = (1, digit)
    for _ in range(1, length):
        ndp = {}
        for (last, rem, total, count), (ways, digit_sums) in dp.items():
            for digit in alphabet:
                if digit == last:
                    continue
                new_total = total + digit
                new_count = count + int(digit == target_digit)
                if new_total > sum_max or new_count > target_count:
                    continue
                key = (digit, (rem * 10 + digit) % modulus, new_total, new_count)
                old_ways, old_sums = ndp.get(key, (0, 0))
                ndp[key] = (old_ways + ways, old_sums + digit_sums + ways * digit)
        dp = ndp
    count_valid = 0
    digit_sum_total = 0
    for (last, rem, total, count), (ways, digit_sums) in dp.items():
        if rem == residue and sum_min <= total <= sum_max and count == target_count:
            count_valid += ways
            digit_sum_total += digit_sums
    return {"count": count_valid, "digit_sum_total": digit_sum_total}

def check(answer, facts):
    alphabet = facts["alphabet"]
    length = facts["length"]
    modulus = facts["modulus"]
    residue = facts["residue"]
    sum_min = facts["sum_min"]
    sum_max = facts["sum_max"]
    target_digit = facts["target_digit"]
    target_count = facts["target_count"]
    # Independent formulation: memoized suffix counts, then weighted summation.
    from functools import lru_cache
    @lru_cache(None)
    def suffix(pos, last, rem, total, target_seen):
        if total > sum_max or target_seen > target_count:
            return (0, 0)
        if pos == length:
            if rem == residue and sum_min <= total <= sum_max and target_seen == target_count:
                return (1, total)
            return (0, 0)
        ways = 0
        sums = 0
        for digit in alphabet:
            if digit != last:
                w, s = suffix(pos + 1, digit, (rem * 10 + digit) % modulus,
                              total + digit, target_seen + int(digit == target_digit))
                ways += w
                sums += s
        return (ways, sums)
    expected = suffix(0, -1, 0, 0, 0)
    return isinstance(answer, dict) and answer.get("count") == expected[0] and answer.get("digit_sum_total") == expected[1]
